<script>
const turnosData=@json($turnosData);const dataFines=turnosData.fines||[];const dataFeriados=turnosData.feriados||[];const dataVigilia=turnosData.vigilia||[];const anioTurnos=@json($anioTurnos);const monthNames=@json(array_map(fn($mes)=>ucfirst(strtolower($mes)),$meses));const groupMembers=[{group:'A',members:[{role:'Líder del turno',name:'Imbaquingo Cabrera Jorge Raúl',icon:'bi-person-gear'},{role:'Periodista 1',name:'Vélez Barreiro María Alejandra',icon:'bi-newspaper'},{role:'Periodista 2',name:'Alvear Cisneros Giovanna Margarita',icon:'bi-newspaper'},{role:'Deportes (* rotan entre 4p)',name:'Sinchire Jiménez Alexis',icon:'bi-trophy'},{role:'Audiovisual',name:'Andrade Braganza Pía',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Estrella Guerra Julio César',icon:'bi-shield-check'}]},{group:'B',members:[{role:'Líder del turno',name:'Quiroz Yánez Gabriela Giannina',icon:'bi-person-gear'},{role:'Periodista 1',name:'Estrella Garcés Santiago Oswaldo',icon:'bi-newspaper'},{role:'Periodista 2',name:'Freire Castañeda Ana Lucía',icon:'bi-newspaper'},{role:'Deportes',name:'Rojas Acevedo Carlos Augusto',icon:'bi-trophy'},{role:'Audiovisual',name:'Núñez del Arco Nieto Ramón Alfredo',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Álvarez Hernández Oscar Alejandro',icon:'bi-shield-check'}]},{group:'C',members:[{role:'Líder del turno',name:'Jumbo Roman Betty Del Rocío',icon:'bi-person-gear'},{role:'Periodista 1',name:'Puga Serrano Kevin Mauricio',icon:'bi-newspaper'},{role:'Periodista 2',name:'Riera Alvear Marcela Fernanda',icon:'bi-newspaper'},{role:'Deportes',name:'Álvarez Duque Paulo Fernando',icon:'bi-trophy'},{role:'Audiovisual',name:'Jarrín Dávila Verónica Alexandra',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Pesantes Cedeño Enrique Alejandro',icon:'bi-shield-check'}]},{group:'D',members:[{role:'Líder del turno',name:'Astudillo Orellana Carlos Giovanny',icon:'bi-person-gear'},{role:'Periodista 1',name:'Jiménez Almeida Richard Marcelo',icon:'bi-newspaper'},{role:'Periodista 2',name:'Aguilar Silva María José',icon:'bi-newspaper'},{role:'Deportes',name:'Flores Trujillo Daniel Sebastián',icon:'bi-trophy'},{role:'Audiovisual',name:'Reinoso Morales Judith Catalina',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Pallero Diego Roberto',icon:'bi-shield-check'}]},{group:'E',members:[{role:'Líder del turno',name:'Castillo Espinoza Carolina Denise',icon:'bi-person-gear'},{role:'Periodista 1',name:'Cáceres Moisés Alejandro',icon:'bi-newspaper'},{role:'Periodista 2',name:'Silva Vaca Orlando Xavier',icon:'bi-newspaper'},{role:'Deportes',name:'Sinchire Jiménez Alexis',icon:'bi-trophy'},{role:'Audiovisual',name:'Fernández Arguello Samuel Javier',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Sánchez Cevallos Marco Vinicio',icon:'bi-shield-check'}]},{group:'F',members:[{role:'Líder del turno',name:'Gavilanes Venegas Eugenia Paola',icon:'bi-person-gear'},{role:'Periodista 1',name:'Jara Cherrez Mónica Jacqueline',icon:'bi-newspaper'},{role:'Periodista 2',name:'Sánchez González Michelle',icon:'bi-newspaper'},{role:'Deportes',name:'Rojas Acevedo Carlos Augusto',icon:'bi-trophy'},{role:'Audiovisual',name:'Bustillos Jorge Andrés',icon:'bi-camera-video'},{role:'Guardia pasiva Emerg',name:'Estrella Guerra Julio César',icon:'bi-shield-check'}]}];let currentTab='fines';let calCurrentDate=new Date(anioTurnos,new Date().getMonth(),1);const normalize=(value)=>String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const parseDate=(value)=>value?new Date(value+'T00:00:00'):null;function getGroupBadge(grupo){if(!grupo)return'<span class="text-muted">-</span>';const g=String(grupo).toUpperCase();return`<span class="badge-group badge-${g.toLowerCase()}">${g}</span>`}function groupMatches(itemGroup,filter){if(!filter)return true;const map={A:'1',B:'2',C:'3',D:'4',E:'5'};const reverse={1:'A',2:'B',3:'C',4:'D',5:'E'};const group=String(itemGroup||'').toUpperCase();return group===filter||map[group]===filter||group===(reverse[filter]||'')}function renderHeaders(){const headerRow=document.getElementById('tableHeader');if(currentTab==='fines'){headerRow.innerHTML='<th>Mes</th><th>Fin de semana</th><th>Fechas</th><th>Jefe de turno</th><th>Grupo</th><th>Deportes</th>'}else if(currentTab==='feriados'){headerRow.innerHTML='<th>Feriado</th><th>Fecha</th><th>Grupo</th><th>Deportes</th>'}else if(currentTab==='vigilia'){headerRow.innerHTML='<th>Semana</th><th>Fechas</th><th>Grupo</th><th>Turno de vigilia</th><th>Integrantes</th>'}}function emptyRow(colspan){return`<tr><td colspan="${colspan}" class="text-muted p-4">No hay registros para los filtros seleccionados.</td></tr>`}function renderTable(){if(currentTab==='calendario'){renderCalendar();return}if(currentTab==='integrantes'){renderIntegrantes();return}renderHeaders();const search=normalize(document.getElementById('searchInput').value.trim());const monthFilter=document.getElementById('monthSelect').value;const groupFilter=document.getElementById('groupSelect').value;const tbody=document.getElementById('tableBody');if(currentTab==='fines'){const filtered=dataFines.filter((item)=>{const searchable=normalize([item.jefe_turno,item.deportes,item.mes,item.fecha_label].join(' '));return(!search||searchable.includes(search))&&(!monthFilter||item.mes===monthFilter)&&groupMatches(item.grupo,groupFilter)});tbody.innerHTML=filtered.length?filtered.map((item)=>`<tr><td class="fw-bold text-secondary">${item.mes}</td><td class="fw-bold">${item.fin_semana_label}</td><td>${item.fecha_label||'-'}</td><td>${item.jefe_turno||'-'}</td><td>${getGroupBadge(item.grupo)}</td><td class="text-deportes">${item.deportes||'Sin asignación'}</td></tr>`).join(''):emptyRow(6)}else if(currentTab==='feriados'){const filtered=dataFeriados.filter((item)=>{const searchable=normalize([item.feriado,item.deportes,item.fecha,item.mes].join(' '));return(!search||searchable.includes(search))&&(!monthFilter||item.mes===monthFilter)&&groupMatches(item.grupo,groupFilter)});tbody.innerHTML=filtered.length?filtered.map((item)=>`<tr><td class="fw-bold text-secondary">${item.feriado}</td><td class="fw-bold">${item.fecha}</td><td>${getGroupBadge(item.grupo)}</td><td class="text-deportes">${item.deportes||'Sin asignación'}</td></tr>`).join(''):emptyRow(4)}else if(currentTab==='vigilia'){const activeWeek=getIsoWeek(new Date());const filtered=dataVigilia.filter((item)=>{const personas=(item.personas||[]).join(' ');const searchable=normalize([personas,item.fecha_label,item.semana].join(' '));return(!search||searchable.includes(search))&&groupMatches(item.grupo,groupFilter)});tbody.innerHTML=filtered.length?filtered.map((item)=>{const isActive=Number(item.semana)===activeWeek;return`<tr class="${isActive?'table-success':''}"><td class="fw-bold">Semana ${item.semana}</td><td>${item.fecha_label||'-'}</td><td>${getGroupBadge(item.grupo)}</td><td>${isActive?'<span class="badge-active-turno"><i class="bi bi-clock-fill"></i>22:00 - 23:00</span>':'<span class="text-muted small">Sin turno esta semana</span>'}</td><td><ul class="mb-0 ps-3">${(item.personas||[]).map((persona)=>`<li>${persona}</li>`).join('')||'<li class="text-muted">Sin integrantes</li>'}</ul></td></tr>`}).join(''):emptyRow(5)}}function renderIntegrantes(){const search=normalize(document.getElementById('searchInput').value.trim());const groupFilter=document.getElementById('groupSelect').value;const grid=document.getElementById('groupsGrid');const empty=document.getElementById('groupsEmpty');let hasResults=false;grid.innerHTML=groupMembers.map((group)=>{if(groupFilter&&group.group!==groupFilter)return'';const members=group.members.filter((member)=>{const searchable=normalize([group.group,member.role,member.name].join(' '));return!search||searchable.includes(search)});if(!members.length)return'';hasResults=true;return`<article class="turnos-group-card"><div class="turnos-group-header d-flex align-items-center justify-content-between"><div class="d-flex align-items-center gap-2"><span class="turnos-group-dot badge-${group.group.toLowerCase()}"></span><div class="fw-black text-uppercase">Grupo ${group.group}</div></div><span class="badge bg-light text-dark border rounded-0">${members.length} integrantes</span></div><div>${members.map((member)=>{const isLeader=member.role.includes('Líder');const isGuard=member.role.includes('Guardia');return`<div class="turnos-member ${isLeader?'leader':''} ${isGuard?'guard':''}"><span class="turnos-role"><i class="bi ${member.icon} me-1"></i>${member.role}</span><div class="turnos-member-name">${member.name}</div></div>`}).join('')}</div></article>`}).join('');empty.classList.toggle('d-none',hasResults)}function getIsoWeek(date){const target=new Date(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()));const day=target.getUTCDay()||7;target.setUTCDate(target.getUTCDate()+4-day);const yearStart=new Date(Date.UTC(target.getUTCFullYear(),0,1));return Math.ceil((((target-yearStart)/86400000)+1)/7)}function updateDashboard(){const today=new Date();const todayStart=new Date(today.getFullYear(),today.getMonth(),today.getDate());const nextFds=dataFines.find((item)=>{const end=parseDate(item.fecha_fin);return end&&end>=todayStart})||dataFines[0];if(nextFds){document.getElementById('dashFdsDate').textContent=`${nextFds.mes}: ${nextFds.fecha_label||nextFds.fin_semana_label}`;document.getElementById('dashFdsGroup').textContent=`Grupo ${nextFds.grupo||'-'}`;document.getElementById('dashFdsJefe').textContent=`Jefe: ${nextFds.jefe_turno||'Por asignar'}`}const nextFeriado=dataFeriados.find((item)=>{const date=parseDate(item.fecha_iso);return date&&date>=todayStart})||dataFeriados[0];if(nextFeriado){document.getElementById('dashFeriadoTitle').textContent=nextFeriado.feriado;document.getElementById('dashFeriadoDate').textContent=nextFeriado.fecha;document.getElementById('dashFeriadoGroup').textContent=`Grupo ${nextFeriado.grupo||'-'}`}const activeWeek=getIsoWeek(today);const activeVigilia=dataVigilia.find((item)=>Number(item.semana)===activeWeek)||dataVigilia[0];if(activeVigilia){const integrantes=(activeVigilia.personas||[]).join(', ');document.getElementById('dashVigiliaGroup').innerHTML=`<i class="bi bi-check-circle-fill me-1"></i> Grupo ${activeVigilia.grupo}`;document.getElementById('dashVigiliaMembers').textContent=integrantes||'Sin integrantes';document.getElementById('dashVigiliaMembers').title=integrantes}}function initCalendarSelects(){const monthSel=document.getElementById('calMonthSelect');const yearSel=document.getElementById('calYearSelect');monthSel.innerHTML=monthNames.map((name,index)=>`<option value="${index}">${name}</option>`).join('');yearSel.innerHTML=`<option value="${anioTurnos}">${anioTurnos}</option><option value="${anioTurnos+1}">${anioTurnos+1}</option>`;monthSel.addEventListener('change',()=>{calCurrentDate.setMonth(Number(monthSel.value));renderCalendar()});yearSel.addEventListener('change',()=>{calCurrentDate.setFullYear(Number(yearSel.value));renderCalendar()});document.getElementById('calPrevBtn').addEventListener('click',()=>{calCurrentDate.setMonth(calCurrentDate.getMonth()-1);renderCalendar()});document.getElementById('calNextBtn').addEventListener('click',()=>{calCurrentDate.setMonth(calCurrentDate.getMonth()+1);renderCalendar()});document.getElementById('calTodayBtn').addEventListener('click',()=>{calCurrentDate=new Date();renderCalendar()})}function renderCalendar(){const year=calCurrentDate.getFullYear();const month=calCurrentDate.getMonth();document.getElementById('calMonthSelect').value=month;document.getElementById('calYearSelect').value=year;const grid=document.getElementById('calendarDaysGrid');grid.innerHTML='';const firstDay=new Date(year,month,1);const lastDay=new Date(year,month+1,0);const daysInMonth=lastDay.getDate();let startingDayIndex=firstDay.getDay()-1;if(startingDayIndex===-1)startingDayIndex=6;for(let i=0;i<startingDayIndex;i++){grid.innerHTML+='<div class="calendar-day-cell empty"></div>'}const today=new Date();for(let day=1;day<=daysInMonth;day++){const currentDate=new Date(year,month,day);const iso=currentDate.toISOString().slice(0,10);const isToday=today.getDate()===day&&today.getMonth()===month&&today.getFullYear()===year;const events=[];dataFines.forEach((item)=>{if(item.fecha_inicio&&item.fecha_fin&&iso>=item.fecha_inicio&&iso<=item.fecha_fin){events.push(`<div class="event-badge event-fds" title="Jefe: ${item.jefe_turno||'-'} | Deportes: ${item.deportes||'-'}"><strong>FDS:</strong> Gr. ${item.grupo}</div>`)}});dataFeriados.forEach((item)=>{if(item.fecha_iso===iso){events.push(`<div class="event-badge event-feriado" title="${item.feriado} | Deportes: ${item.deportes||'-'}"><strong>Feriado:</strong> ${item.feriado} (Gr. ${item.grupo||'-'})</div>`)}});const week=getIsoWeek(currentDate);const vigilia=dataVigilia.find((item)=>Number(item.semana)===week);if(vigilia){events.push(`<div class="event-badge event-vigilia" title="${(vigilia.personas||[]).join(', ')}"><strong>Vigilia:</strong> Gr. ${vigilia.grupo}</div>`)}grid.innerHTML+=`<div class="calendar-day-cell ${isToday?'today':''}"><div class="day-number">${day}</div><div>${events.join('')}</div></div>`}}function updateVisiblePanels(){const isCalendar=currentTab==='calendario';const isIntegrantes=currentTab==='integrantes';const isVigilia=currentTab==='vigilia';document.getElementById('tableViewContainer').style.display=(isCalendar||isIntegrantes)?'none':'block';document.getElementById('calendarViewContainer').style.display=isCalendar?'block':'none';document.getElementById('integrantesViewContainer').style.display=isIntegrantes?'block':'none';document.getElementById('searchContainer').style.display=isCalendar?'none':'block';document.getElementById('monthFilterContainer').style.display=(isVigilia||isCalendar||isIntegrantes)?'none':'block';document.getElementById('groupFilterContainer').style.display=isCalendar?'none':'block'}document.getElementById('searchInput').addEventListener('input',renderTable);document.getElementById('monthSelect').addEventListener('change',renderTable);document.getElementById('groupSelect').addEventListener('change',renderTable);document.querySelectorAll('.turnos-public-tabs .nav-link').forEach((button)=>{button.addEventListener('click',()=>{document.querySelectorAll('.turnos-public-tabs .nav-link').forEach((item)=>item.classList.remove('active'));button.classList.add('active');currentTab=button.dataset.tab;updateVisiblePanels();renderTable()})});initCalendarSelects();updateVisiblePanels();renderTable();updateDashboard();
</script>
